<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';require_once dirname(__DIR__).'/backend/repositories/OperationalRepository.php';
$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){admin_verify_csrf();admin_require_role(['admin']);$rid=filter_var($_POST['review_id']??null,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');$note=trim((string)($_POST['note']??''));if($rid&&$rid>0){(new OperationalRepository($pdo))->moderateReview((int)$rid,$status,(int)$_SESSION['user_id'],$note?:null);$notice='Review moderation saved.';}}
$payments=$pdo->query('SELECT id,booking_id,method,amount,status,created_at FROM payments ORDER BY id DESC LIMIT 100')->fetchAll();$reviews=$pdo->query('SELECT id,booking_id,rating,comment,status,created_at FROM reviews ORDER BY id DESC LIMIT 100')->fetchAll();$notifications=$pdo->query('SELECT id,booking_id,recipient,channel,template_key,status,attempts,last_error,created_at FROM notifications ORDER BY id DESC LIMIT 100')->fetchAll();$partners=$pdo->query('SELECT id,name,phone,verification_status,status FROM partners ORDER BY id DESC LIMIT 100')->fetchAll();
admin_page_start('Operations'); ?><h1 class="h2 mb-4">Operations</h1><?php if($notice): ?><div class="alert alert-success"><?= e($notice) ?></div><?php endif; ?><div class="row g-4"><div class="col-12"><section class="card"><div class="card-body"><h2 class="h5">Payments</h2><p class="small text-secondary">Provider processing is not enabled. Online payment requests remain pending until a provider is configured.</p><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Booking</th><th>Method</th><th>Amount</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($payments as $r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= (int)$r['booking_id'] ?></td><td><?= e($r['method']) ?></td><td>₹<?= e($r['amount']) ?></td><td><?= e($r['status']) ?></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$payments): ?><tr><td colspan="6" class="text-secondary text-center">No payment records.</td></tr><?php endif; ?></tbody></table></div></div></section></div>
<div class="col-12 col-xl-7"><section class="card"><div class="card-body"><h2 class="h5">Reviews awaiting moderation and history</h2><div class="table-responsive"><table class="table"><thead><tr><th>Booking</th><th>Rating</th><th>Review</th><th>Status</th><th>Moderate</th></tr></thead><tbody><?php foreach($reviews as $r): ?><tr><td>#<?= (int)$r['booking_id'] ?></td><td><?= (int)$r['rating'] ?>/5</td><td><?= e($r['comment']) ?></td><td><?= e($r['status']) ?></td><td><?php if($_SESSION['role']==='admin'&&$r['status']==='pending'): ?><form method="post" class="d-flex gap-1"><input type="hidden" name="_csrf_token" value="<?= e(admin_csrf_token()) ?>"><input type="hidden" name="review_id" value="<?= (int)$r['id'] ?>"><select class="form-select form-select-sm" name="status"><option value="approved">Approve</option><option value="rejected">Reject</option></select><input class="form-control form-control-sm" name="note" maxlength="500" placeholder="Optional note"><button class="btn btn-sm btn-primary">Save</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$reviews): ?><tr><td colspan="5" class="text-center text-secondary">No reviews submitted.</td></tr><?php endif; ?></tbody></table></div></div></section></div>
<div class="col-12 col-xl-5"><section class="card"><div class="card-body"><h2 class="h5">Notification queue</h2><p class="small text-secondary">Records queue here; no delivery provider is configured, so no fake sent status is shown.</p><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Recipient</th><th>Channel</th><th>Status</th></tr></thead><tbody><?php foreach($notifications as $r): ?><tr><td><?= e($r['recipient']) ?></td><td><?= e($r['channel']) ?></td><td><?= e($r['status']) ?></td></tr><?php endforeach; ?><?php if(!$notifications): ?><tr><td colspan="3" class="text-secondary text-center">Queue is empty.</td></tr><?php endif; ?></tbody></table></div></div></section></div>
<div class="col-12"><section class="card"><div class="card-body"><h2 class="h5">Partners</h2><p><a href="manage.php?type=partners">Manage partner records</a></p><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Phone</th><th>Verification</th><th>Status</th></tr></thead><tbody><?php foreach($partners as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['phone']) ?></td><td><?= e($r['verification_status']) ?></td><td><?= e($r['status']) ?></td></tr><?php endforeach; ?><?php if(!$partners): ?><tr><td colspan="4" class="text-secondary text-center">No partners onboarded.</td></tr><?php endif; ?></tbody></table></div></div></section></div></div><?php admin_page_end();
